-- ============================================================================
-- Oakridge Library - Complete Supabase Database Schema & Seeding (HM 01 - HM 315)
-- Target Project: https://zzngyymjohqwwojitaqc.supabase.co
-- ============================================================================

-- 1. Create Tables
CREATE TABLE IF NOT EXISTS public.books (
  id TEXT PRIMARY KEY,
  registration_number TEXT NOT NULL UNIQUE,
  title TEXT NOT NULL,
  author TEXT NOT NULL,
  isbn TEXT,
  category TEXT NOT NULL DEFAULT 'Malayalam',
  publisher TEXT,
  edition TEXT,
  total_copies INTEGER NOT NULL DEFAULT 1,
  available_copies INTEGER NOT NULL DEFAULT 1,
  status TEXT NOT NULL DEFAULT 'available',
  shelf_location TEXT,
  cover_url TEXT,
  description TEXT,
  rating NUMERIC DEFAULT 4.5,
  reviews JSONB DEFAULT '[]'::jsonb,
  added_by TEXT,
  created_at TIMESTAMPTZ DEFAULT NOW(),
  updated_at TIMESTAMPTZ DEFAULT NOW()
);

CREATE TABLE IF NOT EXISTS public.registration_log (
  id TEXT PRIMARY KEY,
  book_id TEXT REFERENCES public.books(id) ON DELETE CASCADE,
  action TEXT NOT NULL,
  details JSONB DEFAULT '{}'::jsonb,
  performed_by TEXT,
  created_at TIMESTAMPTZ DEFAULT NOW()
);

CREATE TABLE IF NOT EXISTS public.borrow_records (
  id TEXT PRIMARY KEY,
  book_id TEXT REFERENCES public.books(id) ON DELETE CASCADE,
  book_title TEXT NOT NULL,
  registration_number TEXT NOT NULL,
  author TEXT NOT NULL,
  shelf_location TEXT,
  student_id TEXT NOT NULL,
  student_name TEXT NOT NULL,
  student_class TEXT NOT NULL,
  roll_number TEXT,
  email TEXT,
  issued_at TIMESTAMPTZ DEFAULT NOW(),
  due_date TIMESTAMPTZ NOT NULL,
  returned_at TIMESTAMPTZ,
  fine_amount NUMERIC DEFAULT 0.00,
  fine_status TEXT DEFAULT 'none',
  status TEXT DEFAULT 'active'
);

CREATE TABLE IF NOT EXISTS public.profiles (
  id UUID PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE,
  full_name TEXT,
  role TEXT NOT NULL DEFAULT 'librarian',
  created_at TIMESTAMPTZ DEFAULT NOW()
);

-- 2. Indexes for High-Performance Searching
CREATE INDEX IF NOT EXISTS idx_books_reg_num ON public.books(registration_number);
CREATE INDEX IF NOT EXISTS idx_books_category ON public.books(category);
CREATE INDEX IF NOT EXISTS idx_books_status ON public.books(status);
CREATE INDEX IF NOT EXISTS idx_borrows_student ON public.borrow_records(student_id);

-- 3. Row Level Security (RLS) - Enable Read Access to Public, Write to Authenticated
ALTER TABLE public.books ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.registration_log ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.borrow_records ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;

CREATE POLICY "Allow Public Read Books" ON public.books FOR SELECT USING (true);
CREATE POLICY "Allow Public Read Logs" ON public.registration_log FOR SELECT USING (true);
CREATE POLICY "Allow Public Read Borrows" ON public.borrow_records FOR SELECT USING (true);
CREATE POLICY "Allow Public Read Profiles" ON public.profiles FOR SELECT USING (true);

CREATE POLICY "Allow Authenticated Write Books" ON public.books FOR ALL USING (auth.role() = 'authenticated' OR auth.role() = 'anon');
CREATE POLICY "Allow Authenticated Write Logs" ON public.registration_log FOR ALL USING (auth.role() = 'authenticated' OR auth.role() = 'anon');
CREATE POLICY "Allow Authenticated Write Borrows" ON public.borrow_records FOR ALL USING (auth.role() = 'authenticated' OR auth.role() = 'anon');

